'use client';

import type { ResourceManagerProps } from "./types";
import { ResourceTable } from "./resource-table";
import { ResourceManagerProvider } from "./resource-manager-context";
import { ResourceFormModalContainer } from "./resource-form-modal-container";
import { ActionButtons } from "./action-buttons";

/**
 * Generic ResourceManager component for displaying and managing resources.
 *
 * - Handles modal state management 
 * - Provides actions for creating, editing, and deleting resources
 * - Includes internal rendering of forms and action menus
 *
 * @template T Resource type
 * @param props ResourceManagerProps<T>
 */
export function ResourceManager({
  data,
  fields,
  onCreate,
  onUpdate,
  resourceName = "Resource",
  title,
  onSelectionChange,
  onDelete,
}: ResourceManagerProps) {
  return (
    <ResourceManagerProvider
      data={data}
      create={onCreate}
      update={onUpdate}
      resourceName={resourceName}
      onSelectionChange={onSelectionChange}
      onDelete={onDelete}
    >
      <div className="container flex flex-col gap-4">
        {/* Header with title */}
        <div className="flex justify-between items-center px-10">
          <h1 className="text-2xl font-bold">{title}</h1>
        </div>
        <ResourceTable
          fields={fields}
        />
        <ActionButtons />
        <ResourceFormModalContainer fields={fields} />
      </div>
    </ResourceManagerProvider>
  );
}

import * as React from "react";
import { Panel, PanelGroup, PanelResizeHandle } from "react-resizable-panels";
import { Checkbox } from "../ui/checkbox";
import type { FieldDef } from './types';
import { useResourceManager } from './resource-manager-context';

export interface ResourceTableProps {
  fields: FieldDef[];
  minColumnWidth?: number;
}

export function ResourceTable({
  fields,
  minColumnWidth = 10,
}: ResourceTableProps) {
  const {
    data,
    selectedIds,
    setSelectedIds,
    handleOpenEdit,
    resourceName,
  } = useResourceManager();

  const [hoveredRow, setHoveredRow] = React.useState<number | null>(null);

  if (!data || data.length === 0) {
    return (
      <div className="text-center py-8 text-muted-foreground">
        No {resourceName.toLowerCase()}s found.
      </div>
    );
  }

  const handleCheckboxChange = (id: string | number) => {
    setSelectedIds(
      selectedIds.includes(id)
        ? selectedIds.filter((selectedId: string | number) => selectedId !== id)
        : [...selectedIds, id]
    );
  };

  return (
    <div className="flex ">

        <div className="flex w-full">
          {/* Checkbox column */}
          <div className="flex flex-col pt-[47px]"> {/* Offset by header height */}
            {data.map((row) => (
              <div 
                key={`checkbox-${row.id}`}
                className="h-[40px] w-10 flex items-center"
              >
                <Checkbox
                  checked={selectedIds.includes(row.id)}
                  onCheckedChange={() => handleCheckboxChange(row.id)}
                  onClick={(e) => e.stopPropagation()}
                />
              </div>
            ))}
          </div>

          {/* Main table */}
          <div className="rounded-md border border-border flex-1">
            <div className="flex min-w-full">
              {/* Main content */}
              <div className="flex-1">
                <PanelGroup 
                  direction="horizontal" 
                  className="min-w-full"
                >
                  {fields.map((field, index) => (
                    <React.Fragment key={field.key}>
                      <Panel 
                        defaultSize={100 / fields.length}
                        minSize={minColumnWidth}
                      >
                        <div className="h-full flex flex-col">
                          {/* Header */}
                          <div className="border-b px-4 py-3 font-medium text-sm">
                            {field.label}
                          </div>
                          {/* Column cells */}
                          <div className="flex-1">
                            {data.map((row, rowIdx) => (
                              <div
                                key={rowIdx}
                                className={`px-4 py-3 text-sm border-b last:border-b-0 min-h-[40px] flex items-center cursor-pointer ${
                                  hoveredRow === rowIdx || selectedIds.includes(row.id) ? 'bg-muted' : ''
                                }`}
                                onClick={() => handleOpenEdit(rowIdx)}
                                onMouseEnter={() => setHoveredRow(rowIdx)}
                                onMouseLeave={() => setHoveredRow(null)}
                              >
                                <div className="truncate w-full">
                                  {field.renderCell(row[field.key]) || '-'}
                                </div>
                              </div>
                            ))}
                          </div>
                        </div>
                      </Panel>
                      {index < fields.length - 1 && (
                        <PanelResizeHandle className="w-0.5 bg-transparent group hover:bg-muted cursor-col-resize transition-all duration-200 ease-in-out flex items-center justify-center">
                          <div className="w-0.5 h-full bg-border group-hover:bg-muted-foreground group-hover:w-1 transition-all duration-200" />
                        </PanelResizeHandle>
                      )}
                    </React.Fragment>
                  ))}
                </PanelGroup>
              </div>
            </div>
          </div>
        </div>
    </div>
  );
}

import { Dialog, DialogTitle } from "@radix-ui/react-dialog";
import { DialogContent, DialogHeader } from "@/components/ui/dialog";
import type { ResourceFormModalProps } from "./form-types.ts";
import { ResourceFormGenerator } from "./resource-form-generator.tsx";


/**
 * Modal component for resource forms
 * 
 * Handles the dialog UI wrapper around the form component
 */
export function ResourceFormModal({
  isOpen,
  onOpenChange,
  initialValues,
  onSubmit,
  onCancel,
  mode,
  resourceName,
  fields
}: ResourceFormModalProps) {
  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="bg-card rounded shadow-lg p-6 min-w-[350px] max-w-[95vw]">
        <DialogHeader>
          <DialogTitle>
            {mode === "add" ? "Create New" : "Edit"} {resourceName}
          </DialogTitle>
        </DialogHeader>
        <ResourceFormGenerator
          fields={fields}
          initialValues={initialValues}
          onSubmit={onSubmit}
          onCancel={onCancel}
          mode={mode}
        />
      </DialogContent>
    </Dialog>
  );
}

import { useForm, Controller } from 'react-hook-form';
import type { FieldValues } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Button } from '@/components/ui/button';
import { InputText } from './inputs/input-text.tsx';
import { InputTextarea } from './inputs/input-textarea.tsx';
import { InputSelect } from './inputs/input-select.tsx';
import { InputFile } from './inputs/input-file.tsx';
import type { ResourceFormGeneratorProps } from './form-types.ts';
import type { ResourceData } from '../types.ts';


/**
 * Dynamically generates a form based on field definitions using React Hook Form
 */
export function ResourceFormGenerator({
  fields, 
  initialValues, 
  onSubmit, 
  onCancel,
  mode 
}: ResourceFormGeneratorProps) {
  // Dynamically build a zod schema based on field definitions
  const generateSchema = () => {
    const schemaMap: Record<string, any> = {};

    fields.forEach((field) => {
      const fieldKey = String(field.key);
      // Handle different field types based on fieldType
      switch(field.fieldType) {
        case 'string':
          schemaMap[fieldKey] = field.required 
            ? z.string().min(1, { message: `${field.label} is required` })
            : z.string().optional();
          break;
        case 'file':
          schemaMap[fieldKey] = field.required
            ? z.any().refine(val => val instanceof File, { message: `${field.label} is required` })
            : z.any().optional();
          break;
        // Ready for future expansion with other field types
        default:
          // Default to string for now
          schemaMap[fieldKey] = field.required 
            ? z.string().min(1, { message: `${field.label} is required` })
            : z.string().optional();
      }
    });

    return z.object(schemaMap);
  };

  const schema = generateSchema();

  // Use FieldValues for react-hook-form generics for compatibility
  const {
    control,
    handleSubmit,
    formState: { errors },
  } = useForm<FieldValues>({
    resolver: zodResolver(schema),
    defaultValues: initialValues as any,
  });

  // Form submission handler
  const onFormSubmit = (data: FieldValues) => {
    onSubmit(data as Partial<ResourceData>);
  };

  return (
    <form onSubmit={handleSubmit(onFormSubmit)} className="space-y-4">
      {fields.map((field) => {
        const fieldKey = String(field.key);
        return (
          <div key={fieldKey} className="space-y-2">
            <label 
              htmlFor={fieldKey} 
              className="block text-sm font-medium text-gray-700"
            >
              {field.label} {field.required && <span className="text-red-500">*</span>}
            </label>

            <Controller
              name={fieldKey}
              control={control}
              render={({ field: formField }) => {
                // Render different input types
                switch (field.inputType) {
                  case 'text':
                    return (
                      <InputText id={fieldKey} field={formField} />
                    );
                  case 'textarea':
                    return (
                      <InputTextarea id={fieldKey} field={formField} />
                    );
                  case 'select':
                    return (
                      <InputSelect id={fieldKey} label={field.label} field={formField} options={field.options} />
                    );
                  case 'file':
                    return (
                      <InputFile id={fieldKey} field={formField} />
                    );
                  default:
                    return <InputText id={fieldKey} field={formField} />;
                }
              }}
            />

            {errors[fieldKey] && (
              <p className="text-red-500 text-sm">
                {errors[fieldKey]?.message?.toString()}
              </p>
            )}
          </div>
        );
      })}

      <div className="flex justify-end space-x-2 pt-4">
        <Button type="button" variant="default" onClick={onCancel}>
          Cancel
        </Button>
        <Button type="submit" variant="default">
          {mode === 'add' ? 'Create' : 'Update'}
        </Button>
      </div>
    </form>
  );
}

import { Input } from '@/components/ui/input';
import type { ControllerRenderProps } from 'react-hook-form';

interface InputTextProps {
  id: string;
  field: ControllerRenderProps<any, string>;
}

export function InputText({ id, field }: InputTextProps) {
  const value = field.value ?? '';
  return (
    <Input
      id={id}
      type="text"
      className="w-full"
      {...field}
      value={value}
    />
  );
}

import { Textarea } from '@/components/ui/textarea';
import type { ControllerRenderProps } from 'react-hook-form';

interface InputTextareaProps {
  id: string;
  field: ControllerRenderProps<any, string>;
}

export function InputTextarea({ id, field }: InputTextareaProps) {
  const value = field.value ?? '';
  return (
    <Textarea
      id={id}
      className="w-full p-2 border border-gray-300 rounded-md"
      rows={4}
      {...field}
      value={value}
    />
  );
}

import { Select, SelectTrigger, SelectValue, SelectContent, SelectGroup, SelectItem, SelectLabel } from '@/components/ui/select';
import type { ControllerRenderProps } from 'react-hook-form';

interface Option {
  label: string;
  value: string;
}

interface InputSelectProps {
  id: string;
  label: string;
  field: ControllerRenderProps<any, string>;
  options?: Option[];
}

export function InputSelect({ id, label, field, options }: InputSelectProps) {
  const value = field.value ?? '';
  return (
    <Select value={value} onValueChange={field.onChange}>
      <SelectTrigger className="w-full">
        <SelectValue placeholder={`Select ${label}`} />
      </SelectTrigger>
      <SelectContent>
        <SelectGroup>
          {options && options.length > 0 && <SelectLabel>{label}</SelectLabel>}
          {(options ?? []).map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectGroup>
      </SelectContent>
    </Select>
  );
}

import { Input } from '@/components/ui/input';
import type { ControllerRenderProps } from 'react-hook-form';

interface InputFileProps {
  id: string;
  field: ControllerRenderProps<any, string>;
}

export function InputFile({ id, field }: InputFileProps) {
  return (
    <Input
      id={id}
      type="file"
      className="w-full"
      onChange={e => {
        const file = e.target.files?.[0] || null;
        field.onChange(file);
      }}
    />
  );
}

import type {ReactNode} from 'react';

// General resource manager types
export interface ResourceData {
  id: string | number;
  [key: string]: any;
}

export type InputType = 'text' | 'number' | 'tags' | 'select' | 'textarea' | 'file';

// Only the minimal types for resource manager and table
export interface FieldDef {
  key: string;
  label: string;
  inputType: InputType;
  fieldType: string;
  renderCell: (value: any, row?: any) => ReactNode;
  options?: { label: string; value: string }[];
  required?: boolean;
}

export type ModalMode = "add" | "edit";

export interface ResourceManagerProps {
  title: string;
  resourceName: string;
  data: ResourceData[];
  fields: FieldDef[];
  onCreate: (values: Partial<ResourceData>) => void;
  onUpdate: (id: string , values: Partial<ResourceData>) => void;
  onDelete?: (ids: Array<string | number>) => void;
  defaultValues?: Partial<ResourceData>;
  onSelectionChange?: (selectedIds: Array<string | number>) => void;
}

export interface ResourceTableProps {
  data: ResourceData[];
  fields: FieldDef[];
  onEdit: (index: number) => void;
  onDelete: (index: number) => void;
  renderActionsMenu: (rowIdx: number, onEdit: () => void, onDelete: () => void) => ReactNode;
  resourceName: string;
}

import type { FieldDef } from "../types.ts";
import type { ResourceData } from "../types.ts";

export type ModalMode = "add" | "edit";

export interface ResourceFormGeneratorProps {
  fields: FieldDef[];
  initialValues: Partial<ResourceData>;
  onSubmit: (values: Partial<ResourceData>) => void;
  onCancel: () => void;
  mode: ModalMode;
}

export interface ResourceFormModalProps {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  initialValues: Partial<ResourceData>;
  onSubmit: (values: Partial<ResourceData>) => void;
  onCancel: () => void;
  mode: ModalMode;
  resourceName: string;
  fields: FieldDef[];
}
